// Local onboarding prototype. Authentication controls simulate UI states only.
const $=id=>document.getElementById(id),main=$('content'),heading=$('heading');
let page='welcome',preferredName='',email='',tone='Warm and balanced',busy=false,timer;
const samples={'Warm and balanced':'Hey, how has your day been?','Gentle and reassuring':'Hey. Take your time. How are you feeling?','Playful and casual':'Hey! What kind of day are we having?','Direct and thoughtful':'Hey. What’s on your mind?'};
function el(tag,text,cls){const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(cls)node.className=cls;return node;}
function button(text,action,cls='button'){const b=el('button',text,cls);b.type='button';b.onclick=action;return b;}
function tell(text){$('notice').textContent=text;}
function mark(){const wrap=el('div',undefined,'welcome-mark');wrap.setAttribute('aria-hidden','true');wrap.append($('brand-mark').content.cloneNode(true));return wrap;}
function startChat(){const params=new URLSearchParams({theme:document.documentElement.dataset.theme||'light',first:'1',name:preferredName||'there',tone});location.href='chat-screen.html?'+params;}
function simulate(provider){if(busy)return;busy=true;main.querySelectorAll('button').forEach(b=>b.disabled=true);tell('Opening '+provider+' sign-in…');timer=setTimeout(()=>{busy=false;const result=$('auth-result').value;if(result==='failure'){show('welcome');tell('We couldn’t sign you in. Try again or choose another method.');}else if(result==='cancel'){show('welcome');tell('Sign-in cancelled. Choose an option when you’re ready.');}else{show('name');tell('Sign-in simulated. No account was created.');}},700);}
function show(next){clearTimeout(timer);busy=false;page=next;main.replaceChildren();main.scrollTop=0;heading.textContent=({welcome:'Welcome',email:'Sign in with email',check:'Check your email',name:'Your name',style:'Your conversation'})[page];$('back').hidden=page==='welcome';
if(page==='welcome'){
 const art=el('div',undefined,'welcome-art');art.append(mark());main.append(art,el('div','luni','wordmark'),el('h2','A little company.\nRoom to be you.','welcome-title'),el('p','Your AI companion for everyday conversations.','muted'));
 const buttons=el('div',undefined,'stack');buttons.append(button('Continue with Google',()=>simulate('Google'),'button primary'));
 if($('platform').value==='ios')buttons.append(button('Continue with Apple',()=>simulate('Apple')));
 buttons.append(button('Continue with email',()=>show('email')));main.append(buttons,el('p','Sign in or create an account to get started.','small-note'));
 const legal=el('div',undefined,'legal');legal.append(button('Terms of Service',()=>legalPreview('Terms of Service'),'text-button'),document.createTextNode(' · '),button('Privacy Policy',()=>legalPreview('Privacy Policy'),'text-button'));main.append(legal);
}else if(page==='email'){
 main.append(el('p','We’ll send you a link to sign in.','muted'));const form=el('form'),label=el('label','Email address','field'),input=el('input');input.type='email';input.autocomplete='email';input.inputMode='email';input.required=true;input.value=email;input.placeholder='you@example.com';label.append(input);form.append(label);const submit=el('button','Send sign-in link','button primary');submit.type='submit';form.append(submit);form.onsubmit=e=>{e.preventDefault();if(busy)return;email=input.value.trim();busy=true;submit.disabled=true;submit.textContent='Sending…';submit.setAttribute('aria-busy','true');tell('Simulating an email request…');timer=setTimeout(()=>{busy=false;if($('auth-result').value==='failure'){show('email');tell('Couldn’t send the link. Check your connection and try again.');}else{show('check');tell('Preview only: no email was sent.');}},700);};main.append(form);
}else if(page==='check'){
 main.append(el('p','Use the sign-in link sent to:'),el('p',email,'email-address'),el('p','Open the link on this device to continue.','muted'),button('Preview successful sign-in',()=>{show('name');tell('Email verification simulated.');},'button primary'),button('Resend link',()=>{if(busy)return;busy=true;main.querySelectorAll('button').forEach(b=>b.disabled=true);tell('Simulating resend…');timer=setTimeout(()=>{show('check');tell($('auth-result').value==='failure'?'Couldn’t resend. Try again.':'Preview only: link resent. No email was sent.');},700);}),button('Use a different email',()=>show('email'),'text-button'));
}else if(page==='name'){
 main.append(mark(),el('h2','What should I call you?','step-title'),el('p','A name or nickname is fine. You can change it in settings.','muted'));const form=el('form');form.noValidate=true;const label=el('label','Preferred name','field'),input=el('input');input.autocomplete='nickname';input.maxLength=40;input.value=preferredName;input.placeholder='Your name';input.setAttribute('aria-describedby','name-error');label.append(input);const error=el('p','','error');error.id='name-error';error.setAttribute('role','alert');const submit=el('button','Continue','button primary');submit.type='submit';form.append(label,error,submit);form.onsubmit=e=>{e.preventDefault();if(!input.value.trim()){error.textContent='Enter a name to continue.';input.setAttribute('aria-invalid','true');input.focus();return;}preferredName=input.value.trim();show('style');tell('Choose a style, or skip to start chatting.');};main.append(form);
}else if(page==='style'){
 main.append(el('h2','How would you like to talk?','step-title'),el('p','Pick a starting style. You can change this later.','muted'));const form=el('form'),sample=el('div',undefined,'sample'),sampleText=el('p',samples[tone]);sample.append(el('small','A greeting from Luni'),sampleText);for(const value of Object.keys(samples)){const label=el('label',undefined,'choice'),radio=el('input');radio.type='radio';radio.name='tone';radio.checked=value===tone;radio.onchange=()=>{tone=value;sampleText.textContent=samples[value];};label.append(radio,document.createTextNode(value));form.append(label);}const submit=el('button','Start talking','button primary');submit.type='submit';form.append(sample,submit,button('Skip for now',()=>{tone='Warm and balanced';startChat();},'text-button'));form.onsubmit=e=>{e.preventDefault();startChat();};main.append(form);
}heading.focus({preventScroll:true});}
function legalPreview(title){$('legal-title').textContent=title;$('legal-modal').showModal();}
$('close-legal').onclick=()=>$('legal-modal').close();
$('back').onclick=()=>{show(({email:'welcome',check:'email',name:'welcome',style:'name'})[page]||'welcome');};
$('theme-toggle').onclick=()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';$('theme-toggle').textContent=dark?'Light mode':'Dark mode';};
$('platform').onchange=()=>{show('welcome');tell('Platform preview changed.');};
$('restart').onclick=()=>{preferredName='';email='';tone='Warm and balanced';show('welcome');tell('Preview restarted.');};
show('welcome');
